// Generated by Automated Quality Gate; review before merging.
const { add, subtract, multiply, divide, calculatePercentage, modulo, absoluteDifference } = require('../../src/math');

describe('Math Utility Functions', () => {
  
  describe('Input Validation', () => {
    test('should throw TypeError for non-number inputs', () => {
      expect(() => add('1', 2)).toThrow('Inputs must be valid numbers');
      expect(() => subtract(null, 2)).toThrow('Inputs must be valid numbers');
      expect(() => multiply(undefined, 2)).toThrow('Inputs must be valid numbers');
    });

    test('should throw TypeError for NaN', () => {
      expect(() => divide(NaN, 5)).toThrow('Inputs must be valid numbers');
    });

    test('should throw TypeError for Infinity', () => {
      expect(() => modulo(Infinity, 1)).toThrow('Inputs must be finite numbers');
      expect(() => absoluteDifference(1, -Infinity)).toThrow('Inputs must be finite numbers');
    });
  });

  describe('Arithmetic Operations', () => {
    test('add should return correct sum', () => {
      expect(add(1.5, 2.5)).toBe(4);
      expect(add(-1, -1)).toBe(-2);
    });

    test('subtract should normalize -0 to 0', () => {
      expect(subtract(5, 5)).toBe(0);
      expect(Object.is(subtract(5, 5), -0)).toBe(false);
    });

    test('multiply should normalize -0 to 0', () => {
      expect(multiply(0, -5)).toBe(0);
      expect(Object.is(multiply(0, -5), -0)).toBe(false);
    });
  });

  describe('Division and Modulo', () => {
    test('divide should handle basic division and error on zero', () => {
      expect(divide(10, 2)).toBe(5);
      expect(() => divide(10, 0)).toThrow('Cannot divide by zero');
      expect(() => divide(10, -0)).toThrow('Cannot divide by zero');
    });

    test('modulo should follow mathematical rules', () => {
      expect(modulo(-7, 4)).toBe(1);
      expect(modulo(7, 4)).toBe(3);
    });

    test('modulo should throw on zero divisor', () => {
      expect(() => modulo(10, 0)).toThrow('Cannot modulo by zero');
    });
  });

  describe('Percentage and Absolute Difference', () => {
    test('calculatePercentage should handle zero total and normal values', () => {
      expect(calculatePercentage(50, 100)).toBe(50);
      expect(calculatePercentage(50, 0)).toBe(0);
    });

    test('absoluteDifference should return positive distance', () => {
      expect(absoluteDifference(5, 10)).toBe(5);
      expect(absoluteDifference(10, 5)).toBe(5);
      expect(absoluteDifference(-5, -10)).toBe(5);
    });
  });
});
